// #region 🔖Pool
// Pool MUST create a connection pool from a DATABASE_URL.

pub async fn create_pool(database_url: &str) -> PgPool {
    PgPoolOptions::new()
        .max_connections(20)
        .connect(database_url)
        .await
        .expect("failed to connect to PostgreSQL")
