// #region 🔖Session CRUD
// Session CRUD MUST create, load, and update session metadata.

pub async fn create_session(
    pool: &PgPool,
    session_id: Uuid,
    kit_id: Uuid,
    kit_name: &str,
) -> Result<(), SessionError> {
    let mut tx = pool.begin().await?;

    sqlx::query(
        "INSERT INTO runtime.session (session_id, root_kit_id)
         VALUES ($1, $2)"
    )
    .bind(session_id)
    .bind(kit_id)
    .execute(&mut *tx)
    .await?;

    sqlx::query(
        "INSERT INTO core.kit (session_id, kit_id, name)
         VALUES ($1, $2, $3)"
    )
    .bind(session_id)
    .bind(kit_id)
    .bind(kit_name)
    .execute(&mut *tx)
    .await?;

    tx.commit().await?;
    Ok(())
}

pub async fn load_session_meta(
    pool: &PgPool,
    session_id: Uuid,
) -> Result<(DomainVersion, SemioVersion), SessionError> {
    let row = sqlx::query_as::<_, (i64, i64)>(
        "SELECT domain_version, semio_version FROM runtime.session
         WHERE session_id = $1"
    )
    .bind(session_id)
    .fetch_optional(pool)
    .await?
    .ok_or_else(|| SessionError::SessionNotFound(session_id.to_string()))?;
    Ok(row)
}

pub async fn bump_domain_version(
    pool: &PgPool,
    session_id: Uuid,
    new_version: DomainVersion,
) -> Result<(), SessionError> {
    sqlx::query(
        "UPDATE runtime.session SET domain_version = $2, updated_at = now()
         WHERE session_id = $1"
    )
    .bind(session_id)
    .bind(new_version)
    .execute(pool)
    .await?;
    Ok(())
}

