pub async fn create_session(
    pool: &PgPool,
    session_id: Uuid,
    kit_id: Uuid,
    kit_name: &str,
) -> Result<(), SessionError> {
    let mut tx = pool.begin().await?;

    sqlx::query(
        "INSERT INTO runtime.session (session_id, root_kit_id)
         VALUES ($1, $2)"
    )
    .bind(session_id)
    .bind(kit_id)
    .execute(&mut *tx)
    .await?;

    sqlx::query(
        "INSERT INTO core.kit (session_id, kit_id, name)
         VALUES ($1, $2, $3)"
    )
    .bind(session_id)
    .bind(kit_id)
    .bind(kit_name)
    .execute(&mut *tx)
    .await?;

    tx.commit().await?;
    Ok(())
}

