        envelope: req.envelope,
        command: req.command,
        reply: tx,
    })
    .await
    .map_err(|_| SessionError::ActorGone)?;

    rx.await.map_err(|_| SessionError::ActorGone)??;
    Ok(Json(serde_json::json!({"status": "ok"})))
}

// #endregion 🔖Semio Command
